// @LOG_TRY_BITCH(ARG, PLACE) // :8
async function LOG_TRY_BITCH() {
  // RAW: #LOCALSIZE 1 // :9
  // RAW: #LOCALSSIZE 1 // :10
  // #DIMS PLACE（事件优先级修饰符，JS 侧用 on() 的 TIER 表达） // :11


  await era.print(`%FS_BITCH("LOOKS", ARG)%`); // :14

  if (PLACE == "DUNGEON") { // :16

    if (era.get(`cflag:${arg}:1`) == 2) { // :18

      if (era.get(`abl:${arg}:37`) >= 1 || era.get(`talent:${arg}:76`)) { // :20
        await era.print(`无法压抑自己的性欲，`); // :21
      } else if ((era.get(`cflag:${arg}:580`) + era.get(`cflag:${arg}:581`) + era.get(`cflag:${arg}:582`)) < -5000) { // :22
        await era.print(`对于借款只减少了一点点感到不满，`); // :23
      } else { // :24
        await era.print(`在空闲的时间，`); // :25
      } // :26
    } else if (era.get(`cflag:${arg}:1`) == 3 && era.get(`cflag:${arg_0}:533`) > 1) { // :27
      await era.print(`瞒着同伴偷偷的`); // :28
    } else if (era.get(`cflag:${arg}:500`) == 1) { // :29
      if (era.get(`talent:${arg}:85`) && !(era.get(`talent:${arg}:180`) || era.get(`talent:${arg}:181`))) { // :31
        await era.print(`被强迫`); // :31
      } // :31
      await era.print(`遵照命令，`); // :32
    } else { // :33
      await era.print(`无法压抑自己的性欲，`); // :34
    } // :35
  } else { // :36

    if (era.get(`abl:${arg}:37`) >= 1 || era.get(`talent:${arg}:76`)) { // :38
      await era.print(`无法压抑自己的性欲，`); // :39

    } else if ((era.get(`cflag:${arg}:580`) + era.get(`cflag:${arg}:581`) + era.get(`cflag:${arg}:582`)) < -5000) { // :41
      await era.print(`由于高额的债务，不由得开始`); // :42
    } else { // :43
      await era.print(`冒险资金花光了，`); // :44
    } // :45
  } // :46
  await era.printAndWait(`考虑着出卖肉体的事。`); // :47



}

